function fieldSql(key: string, spec: unknown, bind: Bind): string[] {
	if (Object.prototype.hasOwnProperty.call(TEXT_COLUMNS, key)) { return [textSql(key, TEXT_COLUMNS[key], spec, bind)]; }
	if (Object.prototype.hasOwnProperty.call(JSON_STRING_PATHS, key)) { return [jsonStringSql(key, spec, bind)]; }
	if (Object.prototype.hasOwnProperty.call(JSON_NUMBER_PATHS, key)) { return [jsonInSql(key, JSON_NUMBER_PATHS[key], spec, bind)]; }
	if (key === "sysTrans") { return [booleanSql(key, "core.sys_trans", spec)]; }
	if (key === "createdAt") { return dateSql(key, "core.created_at", spec, bind); }
	// a top-level name no stored document has (`transIdRef`, "0", "1"... the characters of the string `info` param): v1 strictQuery is off, so
	// Mongo sends it as is and nothing matches
	if (!STORED_FIELDS.includes(key.split(".")[0])) { return [absentSql(key, spec)]; }
	return refuse("unsupported_key", `filter key "${shown(key)}"`);
}

