function disjunction(branches: unknown, bind: Bind, depth: number): string {
	if (depth >= MAX_FILTER_DEPTH) { return refuse("unsupported_filter", "$or (nested too deep)"); }
	if (!Array.isArray(branches) || branches.length === 0) { return refuse("unsupported_value", "$or (a non-empty array is expected)"); }
	const compiled = branches.map(branch => {
		if (!isPlainObject(branch)) { return refuse("unsupported_value", "$or (an array of objects is expected)"); }
		const parts = conjunction(branch, bind, depth + 1);
		if (parts.length === 0) { return refuse("unsupported_value", "$or (empty branch)"); }
		return `(${parts.join(" AND ")})`;
	});
	return `(${compiled.join("\n\t\t\tOR ")})`;
}

